def _neg_log10(value: float) -> str:
    """-log10(p) 的确定文本：p==0 -> inf，p==1 -> 0，其余取负对数。"""
    if value <= 0.0:
        return "inf"
    if value >= 1.0:
        return "0"
    return fmt_float(-math.log10(value))


